customise-control.liquid.value:
{%- liquid
  assign policy = product.metafields['$app'].insignia_policy_v2.value | split: ':'
  assign generation = shop.metafields['$app'].insignia_public_config_v2.value.generationHex
  assign required = false
  if generation != blank and policy.size == 3 and policy[0] == generation and policy[2] == 'required'
    assign required = true
  endif
  assign control_tag = 'insignia-buyer'
  if control == 'automatic'
    assign control_tag = 'insignia-theme-integration'
  endif
  assign trigger_label = block.settings.button_label | escape
  if block.settings.button_label == blank
    assign trigger_label = 'insignia.customise' | t
  endif
  if required and localization.country.iso_code != blank
    assign unavailable_variant_ids = product.variants | where: 'available', false | map: 'id' | join: ','
  endif
-%}
{%- if control == 'automatic' and required -%}
  {%- comment -%}
    Manual block + app embed: hide the native purchase controls the embed script will hide before first paint, so the
    manual Customise button does not move when the script arrives. The rule is a strict subset of the script's
    decision in theme-integration.ts: a known required product (this policy check); a same-origin cart/add form
    whose product is this one by data-product-id or a product-id input, outside quick-add and dialog surfaces, that
    holds a purchase button; and a visible manual block for this product inside every section around that form.
    It applies only while the embed element is not yet defined. The script upgrades it and hides the same controls
    itself in one task, so from then on the script alone owns them and can still restore any of them.
  {%- endcomment -%}
  {%- capture pid -%}[data-product-id="{{ product.id }}"]{%- endcapture -%}
  {%- capture other_pid -%}[data-product-id]:not({{ pid }}){%- endcapture -%}
  {%- capture surfaces -%}quick-add-component,sticky-add-to-cart,quick-add-modal,dialog,[role="dialog"]{%- endcapture -%}
  {%- capture sections -%}:is(.shopify-section,section){%- endcapture -%}
  {%- capture manual -%}insignia-buyer[product-id="{{ product.id }}"]:not([data-insignia-auto],[repair],[hidden],[inert],[hidden] *,[inert] *,:is({{ surfaces }}) *)>button[slot="trigger"]:not([hidden]){%- endcapture -%}
  {%- capture controls -%}button[name="add"],button[type="submit"],.sticky-add-to-cart__button,.shopify-payment-button,shopify-accelerated-checkout{%- endcapture -%}
  {%- capture form -%}form:is([action$="/cart/add"],[action$="/cart/add/"],[action$="/cart/add.js"],[action$="/cart/add.js/"]):is([action^="/"]):not([action^="//"],[action*="\\"],:is({{ surfaces }}) *,{{ sections }}:not(:has({{ manual }})) *):is({{ pid }},{{ pid }} *,:not([data-product-id],[data-product-id] *):has(input[name="product-id"][value="{{ product.id }}"]):not(:has(input[name="product-id"]:not([value="{{ product.id }}"])))):not({{ other_pid }},{{ other_pid }} *):has(button:is({{ controls }}):not(insignia-buyer *)){%- endcapture -%}
  <style data-insignia-prepaint>
    :root:has(insignia-theme-integration[product-id="{{ product.id }}"][known-required]:not(:defined)) {{ sections }}:has({{ manual }}) {{ form }} :is({{ controls }}):not(insignia-buyer *){display:none!important}
  </style>
{%- endif -%}
{%- if control == 'automatic' or required -%}
  <{{ control_tag }}
    product-id="{{ product.id }}"
    {% if unavailable_variant_ids != blank %}
      unavailable-variant-ids="{{ unavailable_variant_ids }}"
    {% endif %}
    {% if control == 'automatic' %}
      variant-ids="{{ product.variants | map: 'id' | join: ',' }}"
      auto-placement="{{ block.settings.auto_placement }}"
    {% else %}
      {{ block.shopify_attributes }}
    {% endif %}
    {% if required %}known-required{% endif %}
    proxy-base="{{ routes.root_url }}apps/{{ block.settings.proxy_prefix | escape }}"
    cart-root="{{ routes.root_url }}" country="{{ localization.country.iso_code }}" market-id="{{ localization.market.id }}"
    language="{{ request.locale.iso_code | escape }}" store-name="{{ shop.name | escape }}"
    trigger-label="{{ trigger_label }}"
    button-style="{{ block.settings.button_style | escape }}"
    button-width="{{ block.settings.button_width | escape }}"
    {% if block.settings.button_background != blank %}button-background="{{ block.settings.button_background | escape }}"{% endif %}
    {% if block.settings.button_color != blank %}button-color="{{ block.settings.button_color | escape }}"{% endif %}
    {% if block.settings.override_radius %}button-radius="{{ block.settings.button_radius }}px"{% endif %}
    {% if block.settings.override_border %}button-border-width="{{ block.settings.button_border_width }}px"{% endif %}
    {% if block.settings.button_border_color != blank %}button-border-color="{{ block.settings.button_border_color | escape }}"{% endif %}
    {% if block.settings.button_spacing > 0 %}button-spacing="{{ block.settings.button_spacing }}px"{% endif %}
    {% unless control == 'automatic' %}style="display:contents"{% endunless %}
  >
    {%- comment -%}
      The manual trigger is server-rendered with its final classes and overrides (the same ones styleThemeTrigger
      applies), so it has its size and position from first paint and nothing shifts when the script arrives (#653).
    {%- endcomment -%}
    {%- unless control == 'automatic' -%}
      {%- capture trigger_style -%}
        {%- if block.settings.button_background != blank -%}background-color:{{ block.settings.button_background }};background-image:none;{%- endif -%}
        {%- if block.settings.button_color != blank -%}color:{{ block.settings.button_color }};{%- endif -%}
        {%- if block.settings.override_radius -%}border-radius:{{ block.settings.button_radius }}px;{%- endif -%}
        {%- if block.settings.override_border -%}border-width:{{ block.settings.button_border_width }}px;border-style:solid;{%- endif -%}
        {%- if block.settings.button_border_color != blank -%}border-color:{{ block.settings.button_border_color }};{%- endif -%}
        {%- if block.settings.button_spacing > 0 -%}margin-block:{{ block.settings.button_spacing }}px;{%- endif -%}
        {%- if block.settings.button_width == 'full' -%}width:100%;{%- elsif block.settings.button_width == 'content' -%}width:auto;{%- endif -%}
      {%- endcapture -%}
      <button
        type="button"
        slot="trigger"
        class="button insignia-customise{% if block.settings.button_style == 'primary' %} button--primary{% elsif block.settings.button_style == 'secondary' %} button--secondary button-secondary{% endif %}"
        {% if trigger_style != blank %}style="{{ trigger_style | escape }}"{% endif %}
      >
        {{- trigger_label -}}
      </button>
    {%- endunless -%}
  </{{ control_tag }}>
{%- elsif request.design_mode -%}
  <p {{ block.shopify_attributes }}>Publish required customization for this product to show Customise.</p>
{%- endif -%}

targets.input_query:
query CartTransformRunInput {
  cart {
    lines {
      id
      quantity
      line: attribute(key: "_insignia_line_v3") { value }
      legacy: attribute(key: "_insignia_member_v2") { value }
      cost { amountPerQuantity { currencyCode } }
      sellingPlanAllocation { sellingPlan { id } }
      merchandise {
        __typename
        ... on ProductVariant {
          id
          product {
            id
            registration: metafield(key: "insignia_registration_v2") { value }
            policy: metafield(key: "insignia_policy_v2") { value }
          }
        }
      }
    }
  }
  localization { country { isoCode } market { id } }
  shop {
    localTime { date }
    publicConfig: metafield(key: "insignia_public_config_v2") { value }
  }
}

query Input {
  buyerJourney { step }
  cart {
    lines {
      id
      quantity
      line: attribute(key: "_insignia_line_v3") { value }
      legacy: attribute(key: "_insignia_member_v2") { value }
      cost {
        amountPerQuantity { currencyCode }
        subtotalAmount { amount currencyCode }
      }
      sellingPlanAllocation { sellingPlan { id } }
      merchandise {
        __typename
        ... on ProductVariant {
          id
          product {
            id
            registration: metafield(key: "insignia_registration_v2") { value }
            policy: metafield(key: "insignia_policy_v2") { value }
          }
        }
      }
    }
  }
  localization { country { isoCode } language { isoCode } market { id } }
  shop {
    localTime { date }
    publicConfig: metafield(key: "insignia_public_config_v2") { value }
  }
}
